import{_ as o,r as n,o as p,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Collection - October CMS - 4.x","titleTemplate":false,"description":"Adds a collection of model records to the page.","frontmatter":{"subtitle":"Adds a collection of model records to the page."},"headers":[{"level":2,"title":"Available Properties","slug":"available-properties","link":"#available-properties","children":[]},{"level":2,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[]},{"level":2,"title":"How the Component Variable Works","slug":"how-the-component-variable-works","link":"#how-the-component-variable-works","children":[]},{"level":2,"title":"Performing Queries","slug":"performing-queries","link":"#performing-queries","children":[{"level":3,"title":"Accessing the Entry Type","slug":"accessing-the-entry-type","link":"#accessing-the-entry-type","children":[]},{"level":3,"title":"Paginating Records","slug":"paginating-records","link":"#paginating-records","children":[]},{"level":3,"title":"Searching Records","slug":"searching-records","link":"#searching-records","children":[]}]},{"level":2,"title":"Eager Loading Related Records","slug":"eager-loading-related-records","link":"#eager-loading-related-records","children":[]},{"level":2,"title":"Counting Records","slug":"counting-records","link":"#counting-records","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/components/collection.md","filePath":"4.x/cms/components/collection.md"}'),r={name:"4.x/cms/components/collection.md"};function u(g,a,d,k,h,m){const t=n("pre-heading"),e=n("post-heading");return p(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"Collection",-1)),s(e),a[1]||(a[1]=i(`<p>The <code>collection</code> component displays a collection of entries on the page. The collection component can be used on any page, layout or partial.</p><h2 id="available-properties"><a href="#available-properties" class="header-anchor">#</a> Available Properties</h2><p>The following properties are supported by the component.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>The handle of the <a href="./../tailor/blueprints.html">entry blueprint</a>.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>Number of records to display on a single page. Leave empty to disable pagination.</td></tr><tr><td><strong>pageNumber</strong></td><td>This value is used to determine what page the user is on.</td></tr><tr><td><strong>sortColumn</strong></td><td>Column name the records should be ordered by.</td></tr><tr><td><strong>sortDirection</strong></td><td>Direction the records should be ordered by. Supported values are <code>asc</code> and <code>desc</code>.</td></tr></tbody></table></div><h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h2><p>The following adds a collection of <strong>Blog\\Post</strong> entries to the page. The collection is accessed in Twig by looping the default <code>collection</code> variable.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> collection <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>When multiple collections are used on the same page, the component can be assigned a name <strong>posts</strong> using the component alias and this is the variable name that becomes available to the page. The following collection is accessed using the <code>posts</code> variable instead.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection posts</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Use the <code>is empty</code> or <code>is not empty</code> expression to check if a collection has at least one record available to display.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> posts <span class="token operator">is</span> <span class="token operator">not</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token comment">{# ... #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="how-the-component-variable-works"><a href="#how-the-component-variable-works" class="header-anchor">#</a> How the Component Variable Works</h2><p>The component variable (e.g. <code>collection</code> or your alias like <code>posts</code>) acts as a smart proxy that behaves differently depending on how you access it.</p><p><strong>Accessing attributes</strong> returns the record field value, useful for section and global components.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> section<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p><strong>Iterating directly</strong> returns the loaded records using the component&#39;s default query, useful for collection components.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><strong>Calling a method</strong> starts a new <a href="./../../extend/database/query.html">database model query</a> that can be chained and must end with <code>get()</code> or <code>paginate()</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> featured <span class="token operator">=</span> posts<span class="token punctuation">.</span>where<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>is_featured<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block warning"><p>When accessing the component variable as an attribute (e.g. <code>posts.title</code>) or as a query (e.g. <code>posts.where(...)</code>) the result will be different. Attributes return a stored value from the primary record, whereas methods initiate a new database query.</p></div><h2 id="performing-queries"><a href="#performing-queries" class="header-anchor">#</a> Performing Queries</h2><p>When accessing the component variable using a method it will switch to a <a href="./../../extend/database/query.html">database model query</a>. For example, to only show entries that have a field <code>color</code> with the value <strong>blue</strong> use the <code>where</code> query method. Using the <code>{% set %}</code> Twig tag will assign the result to a new variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> bluePosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>where<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>color<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>blue<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>To show only posts that have a related author, you can use the <code>whereRelation</code> query method. To complete the query, proceed with the <code>get()</code> method. The following lists posts that are assigned to the <code>author</code> with a slug set to <strong>bella-vista</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> authorPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>whereRelation<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>author<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>slug<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>bella-vista<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="accessing-the-entry-type"><a href="#accessing-the-entry-type" class="header-anchor">#</a> Accessing the Entry Type</h3><p>To filter records by their entry type, perform a <code>where()</code> query using the <code>content_group</code> attribute. The following will list posts that use the entry type code <strong>featured_post</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> featuredPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>where<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>content_group<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>featured_post<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="paginating-records"><a href="#paginating-records" class="header-anchor">#</a> Paginating Records</h3><p>You could also apply pagination to the collection with the <code>paginate()</code> method instead. The following will paginate the posts at <strong>10</strong> per page and displays the paginated navigation.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> authorPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>whereRelation<span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span><span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>authorPosts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block tip"><p>See the <a href="./../../ajax/features/pagination.html">Pagination feature</a> to learn more about paging records.</p></div><h3 id="searching-records"><a href="#searching-records" class="header-anchor">#</a> Searching Records</h3><p>To search records, use the <a href="./../../extend/database/query.html"><code>searchWhere()</code> method</a> to perform a search query on a column&#39;s value. The following will search for records the supplied term and columns using a case insensitive query.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foundPages <span class="token operator">=</span> pages<span class="token punctuation">.</span>searchWhere<span class="token punctuation">(</span>searchTerm<span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>title<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>content<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You may also use the <a href="./../../extend/database/relations.html"><code>searchWhereRelation()</code> method</a> to search related records, where the relation name is included in the method for querying the relationship existence.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foundPages <span class="token operator">=</span> pages<span class="token punctuation">.</span>searchWhereRelation<span class="token punctuation">(</span>searchTerm<span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>author<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>title<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="eager-loading-related-records"><a href="#eager-loading-related-records" class="header-anchor">#</a> Eager Loading Related Records</h2><p>In some cases, and for performance reasons, you may wish to eager load related records. Use the <code>load</code> method on the collection, passing the relation name. In the next example, the <code>categories</code> relation will be loaded with every post in the collection.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> authorPosts<span class="token punctuation">.</span>load<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>categories<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="counting-records"><a href="#counting-records" class="header-anchor">#</a> Counting Records</h2><p>Let&#39;s assume you want to display a list of blog categories and count the number of posts in each category. First, define the <a href="./../../element/content/field-entries.html">inverse relation</a> on the category blueprint as <strong>posts</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">posts</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Post
    <span class="token key atrule">inverse</span><span class="token punctuation">:</span> categories
    <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Then, call the <code>withCount</code> function on the collection component, followed by <code>get</code> to return a collection of category records. This will create an attribute on each category called <strong>post_count</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> categories <span class="token operator">=</span> collection<span class="token punctuation">.</span>withCount<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> category <span class="token operator">in</span> categories <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h5</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> category<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span> (<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> category<span class="token punctuation">.</span>post_count <span class="token delimiter punctuation">}}</span></span> posts)<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h5</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../ajax/features/pagination.html">Pagination</a></li><li><a href="./../../extend/database/model.html">Model Queries</a></li><li><a href="./../../extend/database/relations.html">Database Relationships</a></li></ul></div>`,47))])}const v=o(r,[["render",u]]);export{y as __pageData,v as default};
